-- Rebuild Medina Book 4 lesson 1 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 2-6. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '1';
  if existing_count <> 9 then
    raise exception 'Expected 9 Book 4 lesson 1 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الْفِعْلُ الْمُتَعَدِّي وَاللَّازِمُ (переходный и непереходный глагол)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">يَنْقَسِمُ الْفِعْلُ بِاعْتِبَارِ مَعْنَاهُ إِلَى قِسْمَيْنِ: مُتَعَدٍّ وَلَازِمٍ. فَالْمُتَعَدِّي يَتَجَاوَزُ أَثَرُهُ الْفَاعِلَ إِلَى الْمَفْعُولِ بِهِ، وَاللَّازِمُ لَا يَتَعَدَّى أَثَرُهُ الْفَاعِلَ.</span><p class="rule-study-text">Переходный глагол переносит действие от исполнителя на прямое дополнение; непереходный ограничивается исполнителем и прямого дополнения не требует.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مُتَعَدٍّ</span><span class="rule-term-ru">переходный глагол</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ لَازِمٌ (قَاصِرٌ)</span><span class="rule-term-ru">непереходный глагол</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия, страдательное причастие</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Признаки и примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُتَعَدِّي</span><span class="rule-table-ru">переходный</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَقْبَلُ هَاءَ الضَّمِيرِ الْعَائِدَةَ إِلَى الْمَفْعُولِ بِهِ، وَيُصَاغُ مِنْهُ اسْمُ الْمَفْعُولِ مُبَاشَرَةً.</span><span class="rule-table-ru">принимает присоединённое местоимение «его/её», возвращающееся к дополнению; страдательное причастие образуется прямо, без предлога</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ وَحَفِظْتُهُ.</span><span class="rule-table-ru">Я понял урок и выучил его.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اللَّازِمُ</span><span class="rule-table-ru">непереходный</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">لَا يَحْتَاجُ إِلَى مَفْعُولٍ بِهِ، وَلَا يُصَاغُ مِنْهُ اسْمُ الْمَفْعُولِ إِلَّا مَعَ حَرْفِ جَرٍّ أَوْ ظَرْفٍ.</span><span class="rule-table-ru">не требует прямого дополнения; страдательное причастие образуется только с предлогом или обстоятельством</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَلَسْتُ فِي الْبَيْتِ.</span><span class="rule-table-ru">Я сидел дома.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ وَقَرَأْتُ الْكِتَابَ.</span><span class="rule-example-ru">Я понял урок и прочитал книгу.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">ضَرَبْتُ الْحَيَّةَ وَقَتَلْتُهَا.</span><span class="rule-example-ru">Я ударил змею и убил её.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">بَكَى الطِّفْلُ وَنَامَ.</span><span class="rule-example-ru">Ребёнок заплакал и уснул.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">مَذْهُوبٌ إِلَيْهِ، وَمَخْرُوجٌ مِنْهُ، وَمَجْلُوسٌ فِيهِ، وَمَسِيرٌ وَرَاءَهُ.</span><span class="rule-example-ru">то, куда пошли; то, откуда вышли; то, где сидели; то, позади чего шли — формы с предлогом или обстоятельством.</span></div></div></div></div>', 'Переходный глагол переносит действие от исполнителя на прямое дополнение; непереходный ограничивается исполнителем и прямого дополнения не требует.', 'يَنْقَسِمُ الْفِعْلُ بِاعْتِبَارِ مَعْنَاهُ إِلَى قِسْمَيْنِ: مُتَعَدٍّ وَلَازِمٍ. فَالْمُتَعَدِّي يَتَجَاوَزُ أَثَرُهُ الْفَاعِلَ إِلَى الْمَفْعُولِ بِهِ، وَاللَّازِمُ لَا يَتَعَدَّى أَثَرُهُ الْفَاعِلَ.'),
    (2, 'طَرَائِقُ تَعْدِيَةِ الْفِعْلِ اللَّازِمِ (способы сделать непереходный глагол переходным)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">يُعَدَّى الْفِعْلُ اللَّازِمُ بِثَلَاثِ طَرَائِقَ: بِنَقْلِهِ إِلَى بَابِ أَفْعَلَ، أَوْ إِلَى بَابِ فَعَّلَ، أَوْ بِتَعْدِيَتِهِ بِحَرْفِ الْجَرِّ.</span><p class="rule-study-text">У шарха указаны три способа: перевести глагол в породу أَفْعَلَ, перевести его в породу فَعَّلَ или присоединить подходящий предлог.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три способа</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّرِيقَةُ</span><span class="rule-table-ru">способ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ أَفْعَلَ</span><span class="rule-table-ru">порода с добавочной хамзой</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَبْكَى الرَّجُلُ الطِّفْلَ. أَجْلَسَ الْمُرَاقِبُ الطَّالِبَ.</span><span class="rule-table-ru">Мужчина заставил ребёнка плакать. Контролёр посадил студента.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ فَعَّلَ</span><span class="rule-table-ru">порода с удвоением второй коренной</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَكَّى الرَّجُلُ الطِّفْلَ. جَلَّسَ الْمُرَاقِبُ الطَّالِبَ.</span><span class="rule-table-ru">Мужчина заставил ребёнка плакать. Контролёр посадил студента.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ الْجَرِّ</span><span class="rule-table-ru">предлог</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">غَضِبَ اللَّهُ عَلَى الْيَهُودِ.</span><span class="rule-table-ru">Аллах разгневался на иудеев.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор управления предлогом</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَارُّ وَالْمَجْرُورُ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ غَيْرُ صَرِيحٍ.</span><span class="rule-example-ru">Предлог с именем в родительном состоянии занимает синтаксическое место косвенно выраженного прямого дополнения в винительном статусе.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">نَظَرْتُ إِلَى الْجَبَلِ.</span><span class="rule-example-ru">Я посмотрел на гору.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">رَغِبْتُ فِي السُّنَّةِ.</span><span class="rule-example-ru">Я стремился к Сунне.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">تَمَسَّكْ بِالْفَضِيلَةِ.</span><span class="rule-example-ru">Держись добродетели.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">اِطَّلَعَ الْمُدِيرُ عَلَى الْكِتَابِ.</span><span class="rule-example-ru">Директор ознакомился с книгой.</span></div></div></div></div>', 'У шарха указаны три способа: перевести глагол в породу أَفْعَلَ, перевести его в породу فَعَّلَ или присоединить подходящий предлог.', 'يُعَدَّى الْفِعْلُ اللَّازِمُ بِثَلَاثِ طَرَائِقَ: بِنَقْلِهِ إِلَى بَابِ أَفْعَلَ، أَوْ إِلَى بَابِ فَعَّلَ، أَوْ بِتَعْدِيَتِهِ بِحَرْفِ الْجَرِّ.'),
    (3, 'مِنْ مَعَانِي فَعَّلَ (значения породы فَعَّلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">مِنْ مَعَانِي بَابِ فَعَّلَ: التَّعْدِيَةُ، وَالتَّكْثِيرُ إِذَا كَانَ الْمَفْعُولُ بِهِ كَثِيرًا، وَالْمُبَالَغَةُ إِذَا كَانَ شَيْئًا وَاحِدًا.</span><p class="rule-study-text">В этом уроке порода فَعَّلَ объясняется в трёх значениях: переходность, множественность объекта и усиленность действия над одним объектом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три значения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">التَّعْدِيَةُ</span><span class="rule-table-ru">переходность</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَلَّسَ الْمُرَاقِبُ الطَّالِبَ.</span><span class="rule-table-ru">Контролёр посадил студента.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّكْثِيرُ</span><span class="rule-table-ru">множественность</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَسَّرْتُ الْأَقْلَامَ. فَتَّحْتُ الْأَبْوَابَ.</span><span class="rule-table-ru">Я переломал ручки. Я пооткрывал двери.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبَالَغَةُ</span><span class="rule-table-ru">усиленность</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَسَّرْتُ الْقَلَمَ. فَتَّحْتُ الْبَابَ.</span><span class="rule-table-ru">Я основательно сломал ручку. Я широко открыл дверь.</span></td></tr></tbody></table></div></div></div>', 'В этом уроке порода فَعَّلَ объясняется в трёх значениях: переходность, множественность объекта и усиленность действия над одним объектом.', 'مِنْ مَعَانِي بَابِ فَعَّلَ: التَّعْدِيَةُ، وَالتَّكْثِيرُ إِذَا كَانَ الْمَفْعُولُ بِهِ كَثِيرًا، وَالْمُبَالَغَةُ إِذَا كَانَ شَيْئًا وَاحِدًا.'),
    (4, 'أَرَى مِنْ بَابِ أَفْعَلَ (глагол أَرَى из породы أَفْعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">أَمَّا أَرَى الثُّلَاثِيُّ الْمَزِيدُ فَهُوَ مِنْ بَابِ أَفْعَلَ، وَأَصْلُهُ أَرْأَى؛ حُذِفَتِ الْهَمْزَةُ تَخْفِيفًا، وَهُوَ يَنْصِبُ مَفْعُولَيْنِ.</span><p class="rule-study-text">Простой رَأَى управляет одним дополнением. Производный أَرَى «показал» восходит к أَرْأَى, имеет формы يُرِي и أَرِ и управляет двумя дополнениями.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Сопоставление двух глаголов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущая форма</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительная форма</span></th><th><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْعَمَلُ</span><span class="rule-table-ru">управление</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَأَى</span><span class="rule-table-ru">увидел</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَرَى</span><span class="rule-table-ru">видит</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَ، رَهْ</span><span class="rule-table-ru">увидь; форма с هَاءُ السَّكْتِ</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَنْصِبُ مَفْعُولًا وَاحِدًا</span><span class="rule-table-ru">ставит одно дополнение в винительный статус</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَرَى</span><span class="rule-table-ru">показал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُرِي</span><span class="rule-table-ru">показывает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَرِ</span><span class="rule-table-ru">покажи</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَنْصِبُ مَفْعُولَيْنِ</span><span class="rule-table-ru">ставит два дополнения в винительный статус</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَرِنِي كِتَابَكَ.</span><span class="rule-example-ru">Покажи мне свою книгу.</span></div></div></div></div>', 'Простой رَأَى управляет одним дополнением. Производный أَرَى «показал» восходит к أَرْأَى, имеет формы يُرِي и أَرِ и управляет двумя дополнениями.', 'أَمَّا أَرَى الثُّلَاثِيُّ الْمَزِيدُ فَهُوَ مِنْ بَابِ أَفْعَلَ، وَأَصْلُهُ أَرْأَى؛ حُذِفَتِ الْهَمْزَةُ تَخْفِيفًا، وَهُوَ يَنْصِبُ مَفْعُولَيْنِ.'),
    (5, 'جَمْعُ الْجَمْعِ (множественное от множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">قَدْ يُجْمَعُ الْجَمْعُ، وَجَمْعُ الْجَمْعِ سَمَاعِيٌّ يُحْفَظُ وَلَا يُقَاسُ عَلَيْهِ.</span><p class="rule-study-text">Форма множественного числа иногда сама получает множественное число. Такие формы заучиваются по употреблению и не служат общей моделью.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">единственное число</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ</span><span class="rule-table-ru">множественное число</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَمْعُ الْجَمْعِ</span><span class="rule-table-ru">множественное от множественного</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">إِنَاءٌ</span><span class="rule-table-ru">сосуд</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">آنِيَةٌ</span><span class="rule-table-ru">сосуды</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَوَانٍ</span><span class="rule-table-ru">множество сосудов</span></td></tr><tr><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">سِوَارٌ</span><span class="rule-table-ru">браслет</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَسْوِرَةٌ</span><span class="rule-table-ru">браслеты</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَسَاوِرُ</span><span class="rule-table-ru">множество браслетов</span></td></tr><tr><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">يَدٌ</span><span class="rule-table-ru">рука</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَيْدٍ</span><span class="rule-table-ru">руки</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَيَادٍ</span><span class="rule-table-ru">множество рук</span></td></tr><tr><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">طَرِيقٌ</span><span class="rule-table-ru">дорога</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">طُرُقٌ</span><span class="rule-table-ru">дороги</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">طُرُقَاتٌ</span><span class="rule-table-ru">множество дорог</span></td></tr><tr><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">مَكَانٌ</span><span class="rule-table-ru">место</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَمْكِنَةٌ</span><span class="rule-table-ru">места</span></td><td><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">أَمَاكِنُ</span><span class="rule-table-ru">множество мест</span></td></tr></tbody></table></div></div></div>', 'Форма множественного числа иногда сама получает множественное число. Такие формы заучиваются по употреблению и не служат общей моделью.', 'قَدْ يُجْمَعُ الْجَمْعُ، وَجَمْعُ الْجَمْعِ سَمَاعِيٌّ يُحْفَظُ وَلَا يُقَاسُ عَلَيْهِ.'),
    (6, 'إِنَّمَا (частица ограничения «только»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">تَتَرَكَّبُ إِنَّمَا مِنْ إِنَّ وَمَا الزَّائِدَةِ الْكَافَّةِ؛ فَتُبْطِلُ عَمَلَ إِنَّ فِي الْجُمْلَةِ الِاسْمِيَّةِ، وَتَجْعَلُهَا تَدْخُلُ عَلَى الْجُمْلَةِ الْفِعْلِيَّةِ، وَتُفِيدُ الْحَصْرَ.</span><p class="rule-study-text">После присоединения الكافّة частица مَا прекращает управление إِنَّ, позволяет сочетанию إِنَّمَا входить как в именное, так и в глагольное предложение и придаёт значение ограничения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">مَا الزَّائِدَةُ الْكَافَّةُ</span><span class="rule-term-ru">добавочная مَا, прекращающая управление إِنَّ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْحَصْرُ (التَّعْيِينُ)</span><span class="rule-term-ru">ограничение: утверждение и выделение одного признака без остальных</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">حَرْفُ نَصْبٍ مُهْمَلٌ</span><span class="rule-term-ru">частица винительного управления, действие которой отменено</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ﴾</span><span class="rule-example-ru">Верующие — лишь братья.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْ﴾</span><span class="rule-example-ru">Боятся Аллаха из Его рабов лишь обладающие знанием.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّمَا مُحَمَّدٌ طَالِبٌ.</span><span class="rule-example-ru">Мухаммад — только студент.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор примера</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّ: حَرْفُ نَصْبٍ مُهْمَلٌ لَا عَمَلَ لَهُ، مَبْنِيٌّ عَلَى الْفَتْحِ.</span><span class="rule-example-ru">إِنَّ — частица винительного управления, действие которой отменено; неизменяема и построена на фатхе.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا: حَرْفٌ زَائِدٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">مَا — добавочная неизменяемая частица на сукуне; синтаксического места не имеет.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ: مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">مُحَمَّدٌ — подлежащее именного предложения в именительном статусе; признак — явно выраженная дамма.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">طَالِبٌ: خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">طَالِبٌ — сказуемое именного предложения в именительном статусе; признак — явно выраженная дамма.</span></div></div></div></div>', 'После присоединения الكافّة частица مَا прекращает управление إِنَّ, позволяет сочетанию إِنَّمَا входить как в именное, так и в глагольное предложение и придаёт значение ограничения.', 'تَتَرَكَّبُ إِنَّمَا مِنْ إِنَّ وَمَا الزَّائِدَةِ الْكَافَّةِ؛ فَتُبْطِلُ عَمَلَ إِنَّ فِي الْجُمْلَةِ الِاسْمِيَّةِ، وَتَجْعَلُهَا تَدْخُلُ عَلَى الْجُمْلَةِ الْفِعْلِيَّةِ، وَتُفِيدُ الْحَصْرَ.'),
    (7, 'أُسْلُوبُ التَّحْذِيرِ (конструкция предостережения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">أُسْلُوبُ التَّحْذِيرِ تَنْبِيهُ الْمُخَاطَبِ عَلَى أَمْرٍ مَكْرُوهٍ لِيَجْتَنِبَهُ، وَيُنْصَبُ الْمُحَذَّرُ إِيَّاهُ وَالْمُحَذَّرُ مِنْهُ بِفِعْلَيْنِ مَحْذُوفَيْنِ.</span><p class="rule-study-text">Предостережение обращает внимание собеседника на нежелательное действие. В модели إِيَّاكَ وَالْكَذِبَ оба винительных компонента связаны с подразумеваемыми глаголами.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">إِيَّاكَ وَالْكَذِبَ.</span><span class="rule-example-ru">Берегись лжи.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">إِيَّاكُمَا وَالْغِيبَةَ.</span><span class="rule-example-ru">Вы двое, берегитесь злословия.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">إِيَّاكُمْ وَالزِّنَا.</span><span class="rule-example-ru">Вы, берегитесь прелюбодеяния.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">إِيَّاكُنَّ وَالتَّبَرُّجَ.</span><span class="rule-example-ru">Вы, женщины, берегитесь выставления напоказ своей красоты.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор إِيَّاكَ وَالْكَذِبَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">إِيَّاكَ: ضَمِيرُ نَصْبٍ مُنْفَصِلٌ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ نَصْبٍ، وَهُوَ مَفْعُولٌ بِهِ لِفِعْلٍ مَحْذُوفٍ تَقْدِيرُهُ: أُحَذِّرُ.</span><span class="rule-example-ru">إِيَّاكَ — отдельное винительное местоимение, неизменяемое на фатхе, занимает место прямого дополнения при опущенном глаголе «предостерегаю».</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">وَ: حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">وَ — неизменяемый союз, построенный на фатхе; синтаксического места не имеет.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">الْكَذِبَ: مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَفِعْلُهُ مَحْذُوفٌ تَقْدِيرُهُ: اِحْذَرْ.</span><span class="rule-example-ru">الْكَذِبَ — прямое дополнение в винительном статусе с явной фатхой; его опущенный глагол означает «берегись».</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةُ «الْكَذِبَ» مَعْطُوفَةٌ عَلَى جُمْلَةِ «إِيَّاكَ».</span><span class="rule-example-ru">Подразумеваемое предложение с الْكَذِبَ соединено союзом с подразумеваемым предложением с إِيَّاكَ.</span></div></div></div></div>', 'Предостережение обращает внимание собеседника на нежелательное действие. В модели إِيَّاكَ وَالْكَذِبَ оба винительных компонента связаны с подразумеваемыми глаголами.', 'أُسْلُوبُ التَّحْذِيرِ تَنْبِيهُ الْمُخَاطَبِ عَلَى أَمْرٍ مَكْرُوهٍ لِيَجْتَنِبَهُ، وَيُنْصَبُ الْمُحَذَّرُ إِيَّاهُ وَالْمُحَذَّرُ مِنْهُ بِفِعْلَيْنِ مَحْذُوفَيْنِ.'),
    (8, 'تَأْكِيدُ الْفِعْلِ الْمَاضِي بِاللَّامِ وَقَدْ (усиление прошедшего глагола посредством لَـ и قَدْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا كَانَ جَوَابُ الْقَسَمِ فِعْلًا مَاضِيًا مُثْبَتًا أُكِّدَ بِاللَّامِ وَقَدْ.</span><p class="rule-study-text">Утвердительный глагол прошедшего времени в ответе на клятву усиливается одновременно лямом ответа и частицей «кад».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الْقَسَمِ</span><span class="rule-term-ru">ответная часть после клятвы</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ مُثْبَتٌ</span><span class="rule-term-ru">утвердительный глагол прошедшего времени</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">لَامُ الْجَوَابِ وَقَدْ</span><span class="rule-term-ru">усиливающие لَـ и قَدْ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا﴾</span><span class="rule-example-ru">Клянусь Аллахом, Он предпочёл тебя нам.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَٱلتِّينِ وَٱلزَّيۡتُونِ ١ وَطُورِ سِينِينَ ٢ وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ ٣ لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ ٤﴾</span><span class="rule-example-ru">Клянусь смоковницей и оливой, горой Синин и этим безопасным городом: Мы сотворили человека в наилучшем сложении.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">وَاللَّهِ لَقَدْ فَرِحْتُ بِنَجَاحِكَ.</span><span class="rule-example-ru">Клянусь Аллахом, я действительно обрадовался твоему успеху.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">وَاللَّهِ لَقَدْ فَهِمْتُ الدَّرْسَ.</span><span class="rule-example-ru">Клянусь Аллахом, я действительно понял урок.</span></div></div></div></div>', 'Утвердительный глагол прошедшего времени в ответе на клятву усиливается одновременно лямом ответа и частицей «кад».', 'إِذَا كَانَ جَوَابُ الْقَسَمِ فِعْلًا مَاضِيًا مُثْبَتًا أُكِّدَ بِاللَّامِ وَقَدْ.'),
    (9, 'أَمْسَى (أَمْسَى как одна из сестёр كَانَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">أَمْسَى فِعْلٌ نَاسِخٌ مِنْ أَخَوَاتِ كَانَ، يَرْفَعُ الِاسْمَ وَيَنْصِبُ الْخَبَرَ.</span><p class="rule-study-text">Глагол أَمْسَى входит в группу сестёр كَانَ: его имя стоит в именительном, а сказуемое — в винительном статусе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Управление أَمْسَى</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ أَمْسَى</span><span class="rule-table-ru">имя أَمْسَى</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ أَمْسَى</span><span class="rule-table-ru">сказуемое أَمْسَى</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-table-ru">именительный статус</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-table-ru">винительный статус</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَمْسَى الْجَوُّ بَارِدًا.</span><span class="rule-example-ru">К вечеру погода стала холодной.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَمْسَتِ الْأُمُّ مَرِيضَةً.</span><span class="rule-example-ru">К вечеру мать заболела.</span></div></div></div></div>', 'Глагол أَمْسَى входит в группу сестёр كَانَ: его имя стоит в именительном, а сказуемое — в винительном статусе.', 'أَمْسَى فِعْلٌ نَاسِخٌ مِنْ أَخَوَاتِ كَانَ، يَرْفَعُ الِاسْمَ وَيَنْصِبُ الْخَبَرَ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '1'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '1'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الأَوَّلُ
الفعلُ ينقسمُ باعتبارِ معناه إلى قسمين : مُتَعَدٍٍّ ، ولاَزِمٍ .
1- الْمُتَعَدَّي
المتعدِّي، هو : ما تَجَاوَزَ أَثَرُهُ الفاعلَ إلى المفعولِ به، نحو : فهمتُ الدَّرسَ وقرأتُ الكتابَ.
فهو يحتاجُ إلى فاعلٍ ، ومفعولٍ به .
علامته : قبول الضَّمير ( الهاء ) العائد إلى المفعول به ، نحو : فهمتُ الدرسَ وحفظتُهُ .
ونحو : ضربتُ الْحَيَّةَ وقَتَلْتُهَا .
فضمير الغِيبة في ( حفظتُهُ, وقتلتُها ) عائد إلى المفعول به .
ومن علاماته : أن يُصَاغَ منه اسمُ المفعول مباشرة ( أي : غيرُ مُقْتَرِنٍ بحرفِ جرٍّ ) نحو : مكتوب ، ومضروب ، ومفهوم .
2- اللاَّزِمُ ( القَاصِرُ )
اللاَّزِمُ ، هو : ما لم يتعدَّ أَثَرُهُ الفاعلَ .
نحو : بَكَى الطِّفْلُ ونَامَ . جلستُ في البيتِ. نزل السائقُ من السيارةِ . خرجتُ من البيت. سِرْتُ وَرَاءَهُ .
فهو لا يحتاج إلى مفعول به . ولا يُصَاغ منه اسمُ المفعول إلا بواسطةِ حرفِ جَرٍّ ، أو ظرفٍ ، نحو : مَذْهُوب إليه ، ومَخْرُوج منه ، ومَجْلُوس فيه، ومَسِير وَرَاءَهُ .', 2, 3, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '1' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'طَرَائِقُ تَعْدِيَةِ الفِعْلِ اللاَّزِمِ
لتعدية الفعل اللاَّزم ثلاث طرائق , هي :
أ- نقله إلى باب أَفْعَلَ ، نحو : أَبْكَى الرَّجُلُ الطفلَ . أَجْلَسَ المراقبُ الطَّالِبَ .
ب- نقله إلى باب فَعَّلَ ، نحو : بَكَّى الرَّجُلُ الطفلَ . جلَّس المراقبُ الطَّالِبَ .
ج- تَعْدِيَةُ اللاَّزمِ بواسطةِ حرفِ الجرِّ ، نحو : غَضِبَ اللهُ على اليهودِ . فالمجرور (اليهود ) بمعنى المفعول به ؛ ولذلك نقول في إعرابه : الجار والمجرور في محل نصب مفعول به غير صريح .
ومن الأمثلة قولك: نظرتُ إلى الجبلِ . رَغِبْتُ في السُّنَّةِ . تَمَسَّكْ بِالفَضِيلَةِ . اِطَّلَعَ الْمُدِيرُ على الكِتَابِ .', 3, 4, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '1' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مِنْ مَعَاني فَعَّلَ
1- التَّعْدِيَةُ : نحو : جَلَّسَ الْمُرَاقِبُ الطَّالِبَ .
2- التَّكْثِيرُ : وذلك إذا كان المفعول به كثيرا ، نحو: كَسَّرْتُ الأَقْلامَ . فَتَّحْتُ الأَبْوَابَ .
3- الْمُبَالَغَةُ : وذلك إذا كان المفعول به شيئا واحدا ،نحو:كَسَّرْتُ القَلَمَ . فَتَّحْتُ البابَ.', 4, 4, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '1' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أَرَى من بَـابِ أَفْعَلَ
رَأَى الثُّلاثي المجرَّد، مضارعه : يَرَى ، والأمر منه : رَ ؛ تقول : رَهْ ( بهاء السَّكتْ ) .
وهو ينصب مفعولاً واحداً .
أما أرى الثلاثي المزيد فهو من باب أفعل ، فأصله : أَرْأَى ، حذفت الهمزة تخفيفا، فصار: أَرَى ، ومضارعه : يُرِى ، والأمر منه : أَرِ ؛ تقول: أَرِني كتابَك .
وهو ينصب مفعولين ؛ لأنه مُتَعَدٍّ نُقِل إلى باب أَفْعَل .', 4, 4, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '1' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'جَمْعُ الْجَمْعِ
قد يُجْمَعُ الْجَمْعُ ، وهو سَمَاعِيّ يُحْفَظُ ، ولا يُقاس عليه .
من أمثلته :
إناءٌ - آنيةٌ - أَوَانٍ .
سِوَارٌ - أَسْوِرَةٌ - أَسَاوِرُ .
يَدٌ - أَيْدٍ - أَيَادٍ .
طَرِيقٌ - طُرُقٌ - طُرُقَاتٌ .
مَكَانٌ - أَمْكِنَةٌ - أَمَاكِنُ .', 4, 5, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '1' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'إِنَّمَا
هي عِبَارَةٌ عن دخولِ ( ما ) الزَّائدةِ الكَافَّةِ على ( إنَّ ) .
فإذا دخلت ( ما ) الزَّائدة الكافَّة على ( إنَّ ) أَثَّرَتْ فيها من جهتين :
1- تُبْطِلُ عَمَلَهَا في الجملةِ الاسميَّةِ ، نحو قوله تعالى : ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ﴾ .
2- تَجْعَلُهَا تدخلُ على الجملةِ الفعليَّةِ , كما في قوله تعالى : ﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْ﴾ .
معناها : تُفِيدُ الْحَصْرَ، (التَّعْيِين) أي : إِثْبَاتُ وتَعْيِينُ صفة واحدة دون غيرها من الصفات، نحو : إنما محمدٌ طالبٌ، أَثْبَتْنَا أنه طالبٌ فقط، وليس له صفة أخرى ، فهو ليس بطبيب ، ولا معلّم ... إلخ .
الإعراب : إنَّما محمدٌ طالبٌ .
إنما : إنَّ : حرف نصب مُهْمَل ( لا عمل له ) مبني على الفتح .
ما : حرف زائد مبني على السكون لا محل له من الإعراب .
محمدٌ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
طالبٌ : خبر مرفوع وعلامة رفعه الضمة الظاهرة .', 5, 5, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '1' and sort_order = 6;

